"""Shared-secret hosting adapter for the React UI; design/02 §5.9 and §6."""

import hmac
import logging
import os
import secrets
import time
from http.cookies import CookieError, SimpleCookie
from urllib.parse import parse_qs, urlparse

from recoup.app import RecoupConfig
from recoup.ui.server import UIHandler, UIHTTPServer

LOGIN = b"""<!doctype html><html><head><meta name="viewport" content="width=device-width">
<title>Recoup sign in</title></head><body><h1>Recoup</h1>
<form method="post" action="/login"><label>Workspace access secret
<input type="password" name="secret" required autocomplete="current-password"></label>
<button>Open workspace</button></form></body></html>"""


class HostedHandler(UIHandler):
    def _signed_in(self):
        cookie = SimpleCookie()
        try:
            cookie.load(self.headers.get("Cookie", ""))
        except CookieError:
            return False
        token = cookie.get("recoup_session")
        return bool(token and self.server.sessions.get(token.value, 0) > time.time())

    def _login_page(self, status=200):
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(LOGIN)))
        self.end_headers()
        self.wfile.write(LOGIN)

    def do_GET(self):
        if urlparse(self.path).path == "/_stcore/health":
            self._json({"status": "ok", "ui": "react"})
        elif not self._signed_in():
            if self.path.startswith("/api/"):
                self._json({"error": "Sign in to the workspace."}, 401)
            else:
                self._login_page()
        else:
            super().do_GET()

    def do_POST(self):
        origin = self.headers.get("Origin", "")
        if origin != f"https://{self.headers.get('Host', '')}":
            self._json({"error": "Use the workspace form."}, 403)
            return
        if urlparse(self.path).path == "/login":
            now = time.monotonic()
            if now < self.server.next_login:
                self._login_page(429)
                return
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if not 0 < size <= 4096:
                    raise ValueError
                candidate = parse_qs(self.rfile.read(size).decode()).get("secret", [""])[0]
            except (ValueError, UnicodeDecodeError):
                self._login_page(400)
                return
            if not hmac.compare_digest(candidate.encode(), self.server.secret.encode()):
                self.server.next_login = now + 2
                self._login_page(401)
                return
            self.server.sessions = {
                key: expiry for key, expiry in self.server.sessions.items() if expiry > time.time()
            }
            token = secrets.token_urlsafe(32)
            self.server.sessions[token] = time.time() + 8 * 3600
            self.send_response(303)
            self.send_header("Location", "/")
            self.send_header(
                "Set-Cookie",
                f"recoup_session={token}; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800",
            )
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
        elif not self._signed_in():
            self._json({"error": "Sign in to the workspace."}, 401)
        else:
            # The external origin has been checked; delegate to the local UI adapter.
            del self.headers["Origin"]
            super().do_POST()

    def end_headers(self):
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "same-origin")
        self.send_header("Cache-Control", "no-store")
        self.send_header(
            "Content-Security-Policy",
            "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; "
            "frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
        )
        super().end_headers()

    def log_message(self, format, *args):
        return


class HostedServer(UIHTTPServer):
    def __init__(self, address, config):
        self.secret = os.environ.get("RECOUP_ACCESS_SECRET", "")
        if len(self.secret) < 32 or self.secret == os.environ.get("OPENAI_API_KEY"):
            raise ValueError("Workspace access is not configured.")
        self.sessions = {}
        self.next_login = 0
        self.config = config
        # UIHTTPServer installs the local handler; use the authenticated adapter here.
        super(UIHTTPServer, self).__init__(address, HostedHandler)


def main():
    for name in ("openai", "httpx", "httpcore"):
        logging.getLogger(name).setLevel(logging.CRITICAL)
    config = RecoupConfig.from_env().model_copy(update={"db": "/data/react-recoup.db"})
    server = HostedServer(("0.0.0.0", 8501), config)
    try:
        server.serve_forever()
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

